#!/bin/bash
# GENERATED by tools/host_leaf_suite.py gen-script leaf_render - edit the @leaf
# markers in leaf_render_harness.c, not this file.
# Compiles the unchanged decomp units below, links them with the leaf harness
# and runs the per-function checks under QEMU.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
DECOMP="${DECOMP:-$(cd "$HERE/../.." && pwd)}"
T="${TOOLCHAIN:-$DECOMP/.toolchain}"
OUT="${OUT:-$HERE/build-leaf-render}"
QEMU="${QEMU:-$HOME/.local/share/qemu-user/extracted/usr/bin/qemu-mipsel}"
GCC="$T/gcc-2.7.2-cdk/gcc"
MASPSX="$(echo "$T"/maspsx-*/maspsx.py)"
mkdir -p "$OUT"
export PATH="$T/mipsel-binutils/root/usr/bin:$PATH"
export LD_LIBRARY_PATH="$T/mipsel-binutils/root/usr/lib/x86_64-linux-gnu${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"

compile() {
    local src="$1" obj="$2"; shift 2
    "$GCC" -B"$T/gcc-2.7.2-cdk/" -I"$DECOMP/src/game" -I"$DECOMP/include" -I"$HERE/mocks" "$@" -O1 -G0 -S "$src" -o "$OUT/tmp.s"
    python3 "$MASPSX" "$OUT/tmp.s" | python3 "$HERE/fix_align.py" > "$OUT/tmp.mas.s"
    mipsel-linux-gnu-as -o "$obj" "$OUT/tmp.mas.s"
}

source "$HERE/unit_path.sh"

objects=()
for unit in 80014490 80015830 80021554 8002DFC4 80040734 8004F188 8005D690 80063568 800684AC 8006AB38 8006C84C 8007CACC 80083834 80086C74 80094F4C; do
    compile "$(unit_src "$unit")" "$OUT/$unit.o"
    objects+=("$OUT/$unit.o")
done
compile "$HERE/mocks/bios_mock.c" "$OUT/bios_mock.o"
compile "$HERE/mocks/sound_mock.c" "$OUT/sound_mock.o"
python3 "$HERE/leaf_vectors.py" > "$OUT/leaf_vectors.h"
compile "$HERE/leaf_render_harness.c" "$OUT/leaf_render_harness.o" -I"$OUT" -I"$HERE"
mipsel-linux-gnu-as -o "$OUT/crt0.o" "$HERE/crt0.s" 2>/dev/null
mipsel-linux-gnu-ld -static -e __start -o "$OUT/leaf_render" \
    "$OUT/crt0.o" "$OUT/leaf_render_harness.o" "$OUT/bios_mock.o" "$OUT/sound_mock.o" "${objects[@]}"
"$QEMU" "$OUT/leaf_render"
